package app.patchwork.radar;
import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class ReminderSettingsTest {
 private final long NOW=Instant.parse("2026-10-17T03:00:00Z").toEpochMilli();
 private JSONObject prefs()throws Exception{return new JSONObject("{\"enabled\":true,\"locale\":\"ko\",\"region\":\"kr\",\"games\":[\"wuwa\"],\"kinds\":[\"pickup\",\"event\"],\"offsets\":[1440,60],\"starts\":true,\"quietEnabled\":false,\"characterTone\":true}");}
 private JSONObject entry(String id,String kind)throws Exception{return new JSONObject().put("id",id).put("gameId","wuwa").put("region","global").put("kind",kind).put("title",new JSONObject().put("ko",id).put("en",id)).put("startAt","2026-10-19T03:00:00Z").put("endAt","2026-10-25T03:00:00Z");}
 private JSONObject feed(JSONObject... es)throws Exception{return new JSONObject().put("games",new JSONArray("[{\"id\":\"wuwa\",\"name\":{\"ko\":\"명조\",\"en\":\"Wuthering Waves\"},\"canonicalRegions\":{\"kr\":\"global\"}}]")).put("entries",new JSONArray(Arrays.asList(es)));}
 private JSONObject rules(JSONObject p,String kind,JSONArray start,JSONArray end)throws Exception{JSONObject all=p.optJSONObject("notificationRules");if(all==null){all=ReminderSettings.normalize(p);p.put("notificationRules",all);}all.put(kind,new JSONObject().put("starts",true).put("ends",true).put("startOffsets",start).put("endOffsets",end));return p;}
 @Test public void customStartAndEndAreIndependentForEachKind()throws Exception{JSONObject p=rules(prefs(),"pickup",new JSONArray().put(0).put(60).put(1440),new JSONArray().put(2880).put(90).put(0));rules(p,"event",new JSONArray(),new JSONArray().put(30));List<ReminderPolicy.Reminder> plan=ReminderPolicy.plan(feed(entry("a","pickup"),entry("b","event")),p,NOW,ZoneId.of("UTC"));assertEquals(7,plan.size());assertEquals(1,plan.stream().filter(r->r.entryId.equals("b")).count());assertTrue(plan.stream().anyMatch(r->r.event.equals("end")&&r.offset==0));}
 @Test public void migrationKeepsLegacyOffsetsAndDoesNotEnableExtraAlerts()throws Exception{JSONObject p=prefs().put("starts",false);p.put("notificationRules",ReminderSettings.normalize(p));assertTrue(ReminderSettings.offsets(p,"pickup","start").isEmpty());assertEquals(Arrays.asList(1440,60),ReminderSettings.offsets(p,"event","end"));}
 @Test public void invalidOffsetsAreRejectedAndDuplicatesRemoved()throws Exception{assertEquals(Arrays.asList(10080,60,0),ReminderSettings.clean(new JSONArray("[60,60,0,-1,0.5,10081,10080,\"1440\",null]")));}
 @Test public void exactEndIsDeliveredButExpiredAdvanceRemindersAreNot()throws Exception{JSONObject e=entry("a","pickup"),p=rules(prefs(),"pickup",new JSONArray().put(0),new JSONArray().put(0).put(60));long end=ReminderPolicy.epoch(e.getString("endAt"));assertTrue(ReminderSettings.due(e,p,"end",end,0,end+60000));assertFalse(ReminderSettings.due(e,p,"end",end,60,end));assertFalse(ReminderSettings.due(e,p,"end",end,0,end+7*3600000));assertFalse(ReminderSettings.due(e,p,"end",end,0,end-1));assertFalse(ReminderSettings.due(e,p,"end",end+60000,0,end+60000));}
 @Test public void disabledOrRemovedRuleInvalidatesPreviouslyScheduledAlarm()throws Exception{JSONObject e=entry("a","pickup"),p=rules(prefs(),"pickup",new JSONArray().put(0),new JSONArray().put(0));long end=ReminderPolicy.epoch(e.getString("endAt"));p.getJSONObject("notificationRules").getJSONObject("pickup").put("ends",false);assertFalse(ReminderSettings.due(e,p,"end",end,0,end));}
 @Test public void simultaneousBannersProduceOneAlertForEachTimeAndSeparateTimesStaySeparate()throws Exception{JSONObject a=entry("a","pickup").put("notificationGroup","phase"),b=entry("b","pickup").put("notificationGroup","phase"),c=entry("c","pickup").put("notificationGroup","phase").put("endAt","2026-10-26T03:00:00Z");JSONObject p=rules(prefs(),"pickup",new JSONArray(),new JSONArray().put(4320).put(2880).put(1440));List<ReminderPolicy.Reminder> plan=ReminderPolicy.plan(feed(c,b,a),p,NOW,ZoneId.of("UTC"));assertEquals(6,plan.size());assertEquals(3,plan.stream().filter(r->r.entryId.equals("a")).count());assertFalse(plan.stream().anyMatch(r->r.entryId.equals("b")));}
 private JSONObject speaker(String id,String entry)throws Exception{return new JSONObject().put("id",id).put("entryId",entry).put("name",new JSONObject().put("ko",id).put("en",id)).put("voice",new JSONObject().put("locale","ko").put("line","창작 "+id).put("original",false).put("reviewedAt","2026-10-17T01:00:00Z").put("sourceUrl","https://example.com/review"));}
 @Test public void threeCharactersRotateByConfiguredOffsetAndUnreviewedLanguageFallsBack()throws Exception{JSONObject a=entry("a","pickup").put("notificationGroup","phase"),b=entry("b","pickup").put("notificationGroup","phase"),c=entry("c","pickup").put("notificationGroup","phase");a.put("notificationCharacters",new JSONArray().put(speaker("A","a")));b.put("notificationCharacters",new JSONArray().put(speaker("B","b")));c.put("notificationCharacters",new JSONArray().put(speaker("C","c")));JSONObject f=feed(c,a,b),p=rules(prefs(),"pickup",new JSONArray(),new JSONArray().put(4320).put(2880).put(1440));long at=ReminderPolicy.epoch(a.getString("endAt"));for(int i=0;i<3;i++){int offset=Arrays.asList(4320,2880,1440).get(i);ReminderMessage m=ReminderMessage.create(f,p,a,"end",at,offset,at-offset*60000L,ZoneId.of("UTC"));assertEquals(Arrays.asList("a","b","c").get(i),m.entryId);assertTrue(m.creative);assertTrue(m.body.contains("가게더 창작 문구"));assertTrue(m.body.contains("10-25 03:00"));}p.put("locale","ja");ReminderMessage m=ReminderMessage.create(f,p,a,"end",at,4320,at-4320*60000L,ZoneId.of("UTC"));assertFalse(m.creative);assertFalse(m.body.contains("창작"));}
 @Test public void missingEvidenceOrOptOutUsesFactualText()throws Exception{JSONObject e=entry("a","pickup"),ch=speaker("A","a");ch.getJSONObject("voice").remove("reviewedAt");e.put("notificationCharacters",new JSONArray().put(ch));JSONObject p=rules(prefs(),"pickup",new JSONArray(),new JSONArray().put(60));long at=ReminderPolicy.epoch(e.getString("endAt"));assertFalse(ReminderMessage.create(feed(e),p,e,"end",at,60,at-3600000,ZoneId.of("UTC")).creative);p.put("characterTone",false);assertFalse(ReminderMessage.create(feed(e),p,e,"end",at,60,at-3600000,ZoneId.of("UTC")).creative);}
 @Test public void delayedAlertsReportActualRemainingTimeAndMinutesAreNotRoundedToZeroHours(){assertEquals("종료까지 30분",ReminderMessage.timing("ko","end",NOW+30*60000L,NOW));assertEquals("종료까지 2일 23시간",ReminderMessage.timing("ko","end",NOW+4319*60000L,NOW));assertEquals("Ended",ReminderMessage.timing("en","end",NOW-1,NOW));}
}
